function [a] = point_mass(r, rb, mu)
%POINT_MASS  The acceleration of a point mass mu at rb on the satellite at r, less its pull on the Earth (both geocentric).
%   r: real[m][3] (passed in m)
%   rb: real[m][3] (passed in m)
%   mu: real[m^3/s^2] (passed in m^3/s^2)
%   returns a: real[m/s^2][3] (passed in m/s^2)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    a = zeros(3, 1);
    d = (rb - r);
    dn = sqrt(d(1)*d(1) + d(2)*d(2) + d(3)*d(3));
    bn = sqrt(rb(1)*rb(1) + rb(2)*rb(2) + rb(3)*rb(3));
    a = [0; 0; 0];
    i = ((0):((3) - 1)).';
    a((i) + 1) = (mu .* ((reshape(d((i) + 1), [], 1) ./ ((dn * dn) * dn)) - (reshape(rb((i) + 1), [], 1) ./ ((bn * bn) * bn))));
end
